create schema if not exists private; revoke all on schema private from public,anon,authenticated; drop function if exists public.bootstrap_workspace(text); create or replace function private.bootstrap_workspace(workspace_name text, uid uuid) returns uuid language plpgsql security definer set search_path = public,private as $$ declare wid uuid; begin if uid is null then raise exception 'Authentication required'; end if; select m.workspace_id into wid from public.workspace_memberships m where m.user_id=uid and m.status='active' order by m.created_at limit 1; if wid is not null then return wid; end if; insert into public.workspaces(name,created_by) values (coalesce(nullif(trim(workspace_name),''),'Ridgewood'),uid) returning id into wid; insert into public.workspace_memberships(workspace_id,user_id,technical_role,status) values(wid,uid,'owner','active'); return wid; end; $$; revoke all on function private.bootstrap_workspace(text,uuid) from public,anon,authenticated;
